    ah+='<span class="mbar-num">'+res+'</span></div>';
  }
  var specs=d.magic_specialty||[];
  if(specs.length){
    ah+='<div class="spec-row">';
    specs.forEach(function(s){ah+='<span class="spec-tag">'+esc(s)+'</span>';});
    ah+='</div>';
  }
  ai.innerHTML=ah||'<div class="empty">—</div>';
  /* Animate mana bars */
  setTimeout(function(){
    var bc=g('b_cap'),br=g('b_res');
    if(bc)bc.style.width=capPct+'%';
    if(br)br.style.width=resPct+'%';
  },150);

  /* ══════════════════════════
     § III  GRIMOIRE
  ══════════════════════════ */
  var sg=g('spell_grid');
  var spells=d.spells||[];
  if(spells.length){
    var sh='';
    spells.forEach(function(sp){
      sh+='<div class="spell-card">';
      sh+='<div class="spell-name">'+esc(sp.name||'—')+'</div>';
      sh+='<div class="spell-meta">';
      if(sp.rank)sh+='<span class="spell-rank">'+esc(sp.rank)+'</span>';
      if(sp.type)sh+='<span class="spell-type">'+esc(sp.type)+'</span>';
      sh+='</div></div>';
    });
    sg.innerHTML=sh;
  }else{sg.innerHTML='<div class="empty">—</div>';}

  /* ══════════════════════════
     § IV  COMPANIONS
  ══════════════════════════ */
  var ci=g('comp_in');
  var party=d.party||[];
  if(party.length){
    var ph='';
    party.forEach(function(p){
      var init=(p.name||'?').trim().charAt(0).toUpperCase();
      ph+='<div class="party-card">';
      ph+='<div class="party-init">'+esc(init)+'</div>';
      ph+='<div class="party-body">';
      ph+='<div class="party-name">'+esc(p.name||'—')+'</div>';
      var sub=[p.role,p.race].filter(Boolean).join(' · ');
      if(sub)ph+='<div class="party-sub">'+esc(sub)+'</div>';
      if(p.note)ph+='<div class="party-note">'+esc(p.note)+'</div>';
      ph+='</div></div>';
    });
    ci.innerHTML=ph;
  }else{ci.innerHTML='<div class="empty">—</div>';}

  /* ══════════════════════════
     § V  SOUL
  ══════════════════════════ */
  var si=g('soul_in');
  var sv='';
  if(d.personality)sv+='<div class="soul-field"><div class="soul-lbl">'+(TH?'บุคลิก':'Personality')+'</div><div class="soul-val">'+esc(d.personality)+'</div></div>';
  if(d.appearance)sv+='<div class="soul-field"><div class="soul-lbl">'+(TH?'รูปลักษณ์':'Appearance')+'</div><div class="soul-val">'+esc(d.appearance)+'</div></div>';
  if(d.goals)sv+='<div class="soul-field"><div class="soul-lbl">'+(TH?'เป้าหมาย':'Goals')+'</div><div class="soul-val">'+esc(d.goals)+'</div></div>';
  var strs=d.strengths||[];
  if(strs.length){
    sv+='<div class="soul-field"><div class="soul-lbl">'+(TH?'จุดแข็ง':'Strengths')+'</div><div class="trait-row">';
    strs.forEach(function(s){sv+='<span class="trait strength">'+esc(s)+'</span>';});
    sv+='</div></div>';
  }
  var wks=d.weaknesses||[];
  if(wks.length){
    sv+='<div class="soul-field"><div class="soul-lbl">'+(TH?'จุดอ่อน':'Weaknesses')+'</div><div class="trait-row">';
    wks.forEach(function(w){sv+='<span class="trait weakness">'+esc(w)+'</span>';});
    sv+='</div></div>';
  }
  if(d.notes)sv+='<div class="soul-field"><div class="soul-lbl">'+(TH?'บันทึก':'Notes')+'</div><div class="soul-val">'+esc(d.notes)+'</div></div>';
  si.innerHTML=sv||'<div class="empty">—</div>';

  /* ── FOOTER ── */
  g('ff_loc').textContent=d.location||'—';
  g('ff_obj').textContent=d.objective||'—';

})();
</script>
